// Mock queue scan - swap for Plain / Zendesk / Jira search in production
const now = Date.now(); const hrs = h => new Date(now - h*3600e3).toISOString();
const tickets = [
 { id:'T-2001', subject:'Workflow crashes on large payloads', customer:'Acme', owner:'dana', lastUpdate:hrs(61), pingPong:2, linearIssue:'ENG-451', waitingOn:'engineering' },
 { id:'T-2002', subject:'Billing invoice mismatch', customer:'Globex', owner:'', lastUpdate:hrs(50), pingPong:1, linearIssue:'', waitingOn:'' },
 { id:'T-2003', subject:'How to migrate self-host to cloud', customer:'Initech', owner:'marco', lastUpdate:hrs(170), pingPong:1, linearIssue:'', waitingOn:'customer' },
 { id:'T-2004', subject:'SSO loops on Safari', customer:'Umbrella', owner:'priya', lastUpdate:hrs(12), pingPong:6, linearIssue:'', waitingOn:'' }
];
const stuck = tickets.map(t => ({...t, idleHrs: Math.round((now - new Date(t.lastUpdate)) / 3600e3)}))
 .filter(t => t.idleHrs > 48 || t.pingPong >= 4)
 .map(t => {
  let reason, action;
  if (!t.owner) { reason = 'UNOWNED'; action = 'Assign an owner this morning'; }
  else if (t.waitingOn === 'engineering') { reason = 'WAITING ON ENGINEERING'; action = 'Nudge ' + t.linearIssue + ' in Linear with customer impact attached'; }
  else if (t.waitingOn === 'customer' && t.idleHrs > 168) { reason = 'CUSTOMER SILENT 7D+'; action = 'Final follow-up today, then close-pending'; }
  else { reason = 'PING-PONG'; action = 'Break the loop: offer a live call, stop the email thread'; }
  return { ...t, reason, action };
 });
return stuck.map(s => ({ json: s }));

const items = $input.all().map(i => i.json);
if (!items.length) return [];
const groups = {};
for (const t of items) (groups[t.reason] = groups[t.reason] || []).push(t);
let body = 'Stuck-ticket morning sweep (' + items.length + ' need a human):\n';
for (const [reason, list] of Object.entries(groups)) {
  body += '\n== ' + reason + ' ==\n';
  for (const t of list) body += t.id + ' - ' + t.customer + ' - ' + t.subject + '\n  idle ' + t.idleHrs + 'h, owner: ' + (t.owner || 'NONE') + '\n  Next: ' + t.action + '\n';
}
body += '\nRule: a customer having to chase us is a failure.';
return [{ json: { subject: 'Stuck tickets: ' + items.length + ' need a human today', body } }];
